import csv
import sys


def count_nonempty(csv_path, encoding="utf-8-sig"):
    with open(csv_path, newline="", encoding=encoding) as f:
        reader = csv.reader(f)
        header = next(reader, None)
        if header is None:
            return {}
        counts = {col: 0 for col in header}
        for row in reader:
            for i, value in enumerate(row):
                if i < len(header) and value.strip():
                    counts[header[i]] += 1
        return counts


def main():
    if len(sys.argv) != 2:
        print(f"用法: python {sys.argv[0]} <csv文件路径>", file=sys.stderr)
        sys.exit(1)
    counts = count_nonempty(sys.argv[1])
    if not counts:
        print("CSV 文件为空", file=sys.stderr)
        sys.exit(1)
    for col, count in counts.items():
        print(f"{col}: {count}")


if __name__ == "__main__":
    main()
